mapper.select:
SELECT ws.stock_no AS stockNo, ws.qty AS currentQty, DATE_FORMAT(ws.received_at, '%Y-%m-%d %H:%i') AS receivedAt, DATE_FORMAT(ws.expiry_date, '%Y-%m-%d') AS expiryDate, ws.status AS status, mg.group_name AS category, m.material_code AS materialCode, m.material_name AS materialName, m.unit AS unit FROM warehouse_stock ws JOIN material m ON ws.material_code = m.material_code JOIN material_group mg ON m.material_group_id = mg.material_group_id
AND mg.group_name = #{categoryName}
AND m.material_name = #{itemName}
AND ( ws.stock_no LIKE CONCAT('%', #{keyword}, '%') OR mg.group_name LIKE CONCAT('%', #{keyword}, '%') OR m.material_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY ws.received_at DESC
